/**
 * How many rows of a virtual list a generated page should write (#930): measured, not guessed.
 *
 * `scenarios/ssg-virtual/` is one long list (1000 rows of 32 px under a 72 px heading, the list as tall
 * as the screen) generated by `pdx build --ssg`, one route per `serverRows`: 0, 10, 20, 40, 80. For each,
 * at a phone's 390 × 844 and a desktop's 1280 × 800, it measures:
 *   · without JavaScript, the rows of the first screen the file paints by itself;
 *   · on slow 4G with the CPU 4× slower, in cold loads (the median of three): the first contentful
 *     paint, the largest one, when the list's first screen is full of rows, when the app has taken the
 *     page over, and the layout shift;
 *   · the page's size.
 * The numbers are printed and attached. What is held: a list the server writes does not move what it
 * wrote (the spacers keep its height), a page paints the rows it was written with, and the default count
 * fills the first screen at both sizes.
 */
import { test, expect, type Page, type Browser } from './fixture';
import type { Server } from 'node:http';
import { scenarioDist } from './scenarios-build';
import { serveSite } from './static-site';
import { SLOW_4G } from './lcp';
import { DEFAULT_SERVER_ROWS } from '../../core/src/server/virtual';

const COUNTS = [0, 10, 20, 40, 80];
const VIEWPORTS = [{ name: 'phone', width: 390, height: 844 }, { name: 'desktop', width: 1280, height: 800 }];
const ROW = 32;
const HEADING = 72;
const RUNS = 3;

let site: { url: string; server: Server };
test.beforeAll(async () => { site = await serveSite(scenarioDist('ssg-virtual')); });
test.afterAll(async () => { await new Promise((r) => site.server.close(r)); });

/** The rows a list as tall as the screen shows at once, under the heading. */
const capacity = (height: number) => Math.ceil((height - HEADING) / ROW);

/** Rows of the list inside its visible box, now. */
const rowsInView = (page: Page) => page.evaluate(() => {
    const list = document.querySelector('[data-test="list"]')!;
    const box = list.getBoundingClientRect();
    return Array.from(list.querySelectorAll('li[data-virtual-index]')).filter((li) => {
        const r = li.getBoundingClientRect();
        return r.height > 0 && r.bottom > box.top && r.top < box.bottom;
    }).length;
});

interface Load { fcp: number; lcp: number; filled: number; adopted: number; cls: number; shifts: string[] }

/** One cold load, throttled, with what the page recorded from before its first byte was parsed. */
async function coldLoad(browser: Browser, route: string, viewport: { width: number; height: number }): Promise<Load> {
    const context = await browser.newContext({ viewport });
    const page = await context.newPage();
    const errors: string[] = [];
    page.on('pageerror', (e) => errors.push(e.message));
    await page.addInitScript(({ rows }) => {
        const w = window as unknown as { __m: Load };
        w.__m = { fcp: -1, lcp: -1, filled: -1, adopted: -1, cls: 0, shifts: [] };
        new PerformanceObserver((l) => { for (const e of l.getEntries()) if (e.name === 'first-contentful-paint') w.__m.fcp = e.startTime; }).observe({ type: 'paint', buffered: true });
        new PerformanceObserver((l) => { const all = l.getEntries(); w.__m.lcp = all[all.length - 1].startTime; }).observe({ type: 'largest-contentful-paint', buffered: true });
        new PerformanceObserver((l) => {
            type Shift = PerformanceEntry & { value: number; hadRecentInput: boolean; sources: { node: Node | null; previousRect: DOMRectReadOnly; currentRect: DOMRectReadOnly }[] };
            for (const e of l.getEntries() as Shift[]) {
                if (e.hadRecentInput) continue;
                w.__m.cls += e.value;
                // What moved, for the failure: each source's element and its two rects.
                for (const s of e.sources) {
                    const el = s.node instanceof Element ? s.node : s.node?.parentElement;
                    const what = el ? `<${el.localName}${el.className ? ` class="${el.className}"` : ''}${el.getAttribute('data-virtual-index') !== null ? ` #${el.getAttribute('data-virtual-index')}` : ''}>` : String(s.node);
                    w.__m.shifts.push(`${what} ${Math.round(s.previousRect.y)}→${Math.round(s.currentRect.y)} h ${Math.round(s.previousRect.height)}→${Math.round(s.currentRect.height)} (${e.value.toFixed(4)} at ${Math.round(e.startTime)} ms)`);
                }
            }
        }).observe({ type: 'layout-shift', buffered: true });
        // Each frame until both are seen: the first screen full of rows, and the outlet taken over.
        const frame = (): void => {
            const list = document.querySelector('[data-test="list"]');
            if (list && w.__m.filled < 0) {
                const box = list.getBoundingClientRect();
                const shown = Array.from(list.querySelectorAll('li[data-virtual-index]')).filter((li) => {
                    const r = li.getBoundingClientRect();
                    return r.height > 0 && r.bottom > box.top && r.top < box.bottom;
                }).length;
                if (shown >= rows) w.__m.filled = performance.now();
            }
            const outlet = document.querySelector('pdx-router-outlet');
            if (outlet && w.__m.adopted < 0 && document.readyState !== 'loading' && !outlet.hasAttribute('data-pdx-ssg')) w.__m.adopted = performance.now();
            if (w.__m.filled < 0 || w.__m.adopted < 0) requestAnimationFrame(frame);
        };
        requestAnimationFrame(frame);
    }, { rows: capacity(viewport.height) });
    const cdp = await context.newCDPSession(page);
    await cdp.send('Network.enable');
    await cdp.send('Network.emulateNetworkConditions', SLOW_4G);
    await cdp.send('Emulation.setCPUThrottlingRate', { rate: 4 });
    await page.goto(`${site.url}${route}`, { waitUntil: 'load' });
    await page.waitForFunction(() => {
        const m = (window as unknown as { __m: { filled: number; adopted: number } }).__m;
        return m.filled >= 0 && m.adopted >= 0;
    }, undefined, { timeout: 30_000 });
    // Settled: a shift or a larger paint after the take-over still counts.
    await page.waitForTimeout(1_000);
    const m = await page.evaluate(() => (window as unknown as { __m: Load }).__m);
    await context.close();
    expect(errors, `${route}: errors on the page`).toEqual([]);
    return { fcp: Math.round(m.fcp), lcp: Math.round(m.lcp), filled: Math.round(m.filled), adopted: Math.round(m.adopted), cls: Number(m.cls.toFixed(4)), shifts: m.shifts };
}

const median = (xs: number[]) => [...xs].sort((a, b) => a - b)[Math.floor(xs.length / 2)];

// #966: each page carries its route's stylesheet inline, so it paints styled with no round trip of its
// own; the file is fetched once, by Vite's loader when the page is taken over, not twice.
test('each page carries its route\'s stylesheet inline, and the file is fetched once', async ({ page }) => {
    for (const count of COUNTS) {
        const route = `/rows-${count}`;
        const html = await (await page.request.get(`${site.url}${route}`)).text();
        expect(html, `${route}: its route's stylesheet is not in the page`).toMatch(new RegExp(`<style data-pdx-route-css="assets/rows-${count}-[^"]+\\.css">`));
        const fetched: string[] = [];
        const onRequest = (r: { url(): string }) => { if (new RegExp(`/assets/rows-${count}-[^/]+\\.css$`).test(r.url())) fetched.push(r.url()); };
        page.on('request', onRequest);
        await page.goto(`${site.url}${route}`);
        await expect(page.locator('pdx-router-outlet')).not.toHaveAttribute('data-pdx-ssg');
        page.off('request', onRequest);
        expect(fetched, `${route}: its stylesheet was fetched ${fetched.length} times`).toHaveLength(1);
    }
});

for (const viewport of VIEWPORTS) {
    test.describe(`at ${viewport.width} × ${viewport.height}`, () => {
        test('each count: what the file paints, what a cold load measures, and what it costs', async ({ browser }) => {
            test.setTimeout(10 * 60_000);
            const rows: Record<string, unknown>[] = [];
            for (const count of COUNTS) {
                const route = `/rows-${count}`;
                const bytes = (await (await browser.newContext()).request.get(`${site.url}${route}`).then((r) => r.body())).length;

                // Without JavaScript: what the file alone shows on the first screen.
                const off = await browser.newContext({ viewport, javaScriptEnabled: false });
                const plain = await off.newPage();
                await plain.goto(`${site.url}${route}`);
                const painted = await rowsInView(plain);
                await off.close();
                expect(painted, `${route}: the file paints the rows it holds, up to a screen`).toBe(Math.min(count, capacity(viewport.height)));

                const loads: Load[] = [];
                for (let i = 0; i < RUNS; i++) loads.push(await coldLoad(browser, route, viewport));
                const cls = Math.max(...loads.map((l) => l.cls));
                expect(cls, `${route}: the rows the client renders moved what was on the screen:\n  ${loads.flatMap((l) => l.shifts).join('\n  ')}`).toBeLessThan(0.01);
                rows.push({
                    serverRows: count, htmlKb: Number((bytes / 1024).toFixed(1)), paintedWithoutJs: painted, screenRows: capacity(viewport.height),
                    fcp: median(loads.map((l) => l.fcp)), lcp: median(loads.map((l) => l.lcp)), filled: median(loads.map((l) => l.filled)),
                    adopted: median(loads.map((l) => l.adopted)), clsMax: cls,
                });
            }
            console.log(`[ssg-virtual] ${viewport.width}x${viewport.height}`);
            console.table(rows);
            await test.info().attach(`ssg-virtual ${viewport.name}`, { body: JSON.stringify(rows, null, 2), contentType: 'application/json' });
        });

        test(`the default count, ${DEFAULT_SERVER_ROWS}, fills the first screen`, () => {
            expect(DEFAULT_SERVER_ROWS, `a ${viewport.width} × ${viewport.height} screen shows ${capacity(viewport.height)} rows of ${ROW} px`).toBeGreaterThanOrEqual(capacity(viewport.height));
        });
    });
}
